def validate_required_params(params: dict[str, object] | None, required_keys: list[str]) -> list[str]:
    """Validate required API request parameters.

    This function returns a list of missing required parameter names.

    Rules:
    - A parameter is considered "present" if the key exists in `params`, regardless of the value.
      For example, 0, False, "", and None still count as present if the key exists.
    - `params=None` is treated as an empty parameter mapping.
    - `required_keys` must be a list of non-empty strings.
    - Duplicate keys in `required_keys` are ignored (first occurrence wins) to keep results stable.

    Raises:
    - TypeError: if params is not a dict (and not None), or required_keys is not a list of str.
    - ValueError: if any required key is an empty string.
    """
    if params is None:
        params_dict: dict[str, object] = {}
    elif isinstance(params, dict):
        params_dict = params
    else:
        raise TypeError("params must be a dict or None")

    if not isinstance(required_keys, list):
        raise TypeError("required_keys must be a list of strings")

    normalized_required: list[str] = []
    seen: set[str] = set()
    for key in required_keys:
        if not isinstance(key, str):
            raise TypeError("required_keys must contain only strings")
        if key == "":
            raise ValueError("required_keys must not contain empty strings")
        if key in seen:
            continue
        seen.add(key)
        normalized_required.append(key)

    missing: list[str] = []
    for key in normalized_required:
        if key not in params_dict:
            missing.append(key)
    return missing

